INSERT INTO products (sku, name, image, price, old_price, available, subtitle, advantages, description, specs, keywords) VALUES
('34827519', 'Microsoft Xbox Series X', '/assets/console/xbox.png', 499.99, NULL, 1, 'САМАЯ БЫСТРАЯ И САМАЯ МОЩНАЯ КОНСОЛЬ XBOX ЗА ВСЮ ИСТОРИЮ.', '["Игры с истинным разрешением 4K","До 120 кадров в секунду","8K HDR High Dynamic Range","Архитектура Xbox Velocity"]', 'КОНСОЛЬ НОВОГО ПОКОЛЕНИЯ Xbox Series X – это игровая консоль нового поколения, которая предлагает Вам широкий выбор цифровых игр, а также поддерживает физические диски с играми. С цифровыми играми все особенно просто – Ваши игры, записи и резервные копии надежно хранятся в облаке. Больше не нужно идти в магазин, чтобы купить игры, или ждать, пока они придут в почтовый офис. Оформляйте предзаказ и предустанавливайте новые игры, чтобы начать играть сразу же после их поступления.  БОЛЬШЕ ИГРАЙТЕ, МЕНЬШЕ ЖДИТЕ Функция Quick Resume позволяет легко переключаться между несколькими играми и мгновенно возвращаться к тому месту, на котором Вы остановились.  ИГРЫ С ИСТИННЫМ РАЗРЕШЕНИЕМ 4K Xbox Series X обеспечивает сенсационно плавную частоту до 120 к/с и яркую и контрастную HDR-картинку. Полностью погрузитесь в игру и наслаждайтесь более четкими персонажами, яркими мирами и невероятными деталями в сверхреалистичном качестве 4K.  12 ТЕРАФЛОПС ВЫЧИСЛИТЕЛЬНОЙ МОЩНОСТИ Благодаря вычислительной мощности 12 терафлопс в системе на кристалле (SOC) и архитектурам AMD Zen 2 и RDNA 2 можно создавать миры, заслуживающие пристального изучения.', '{"Хранение данных":["Объем жесткого диска / накопителя: 1000 ГБ","Тип устройства памяти : SSD"],"Интерфейсы":["HDMI : Да","USB-A 3.1 : Да","NFC : Нет","Оптический аудиовыход : Нет"],"Игровые приставки":["Поддержка носителей : Blu-ray","Поддержка 4K : Да","Аудиосистема : Stereo, Surround, Atmos","Поддержка HDR : Да"],"Браузер и загрузка":["3G : Нет","4G : Нет","5G : Нет","LAN (RJ45) : 10/100/1000","Wi-Fi : Да"],"Общие параметры":["Производитель : Microsoft","Платформа : Xbox Series X","Цвет : Чёрный","В комплекте : Консоль, беспроводной геймпад, кабель HDMI, кабель питания"]}', 'xbox,console,консоль,приставка,microsoft,4k,игровая'),
('72984562', 'PlayStation 4', '/assets/console/playstation4.png', 149.99, 568.99, 1, 'Классическая игровая приставка от Sony.', '["HDR-графика","Игры в Full HD","Поддержка Blu-ray"]', 'PlayStation 4 — популярная игровая консоль от Sony, обеспечивающая великолепное качество графики и большой выбор игр.', '{"Память":["Жесткий диск: 1 ТБ"],"Подключения":["HDMI: Да","USB: Да"],"Особенности":["Blu-ray привод: Да","Wi-Fi: Да"]}', 'playstation,ps4,console,консоль,sony,игровая'),
('18560437', 'Nintendo Switch Lite', '/assets/console/NSwitch.png', 199.99, NULL, 1, 'Компактная и лёгкая консоль Nintendo.', '["Портативность","Яркий экран","Доступ к эксклюзивам"]', 'Switch Lite — идеальный выбор для мобильного гейминга. Поддержка всех цифровых игр Nintendo Switch.', '{"Экран":["5.5\'\' HD","Сенсорный экран"],"Связь":["Wi-Fi","Bluetooth"]}', 'nintendo,switch,console,консоль,портативная,handheld'),
('40392816', 'Samsung Printer', '/assets/printer/samsung.png', 279.99, NULL, 1, 'Надёжный лазерный принтер Samsung.', '["Быстрая печать","Wi-Fi соединение","Компактный дизайн"]', 'Идеально подходит для домашнего и офисного использования. Поддержка беспроводной печати.', '{"Печать":["Скорость: 20 стр/мин","Разрешение: 1200x1200 dpi"],"Интерфейсы":["USB","Wi-Fi"]}', 'printer,принтер,лазерный,samsung,офис'),
('95672041', 'Canon EOS 550', '/assets/photocamera/canonEOS550.png', 599.99, NULL, 1, 'Полупрофессиональная зеркалка Canon.', '["18 МП","Full HD видео","Съёмка RAW"]', 'Камера для начинающих фотографов и видеографов. Простое управление и качественные снимки.', '{"Матрица":["18 МП CMOS"],"Видео":["Full HD 1080p"],"Объектив":["EF / EF-S крепление"]}', 'canon,eos,камера,фотоаппарат,photography'),
('61735824', 'Canon EOS 550 (черный)', '/assets/photocamera/canonEOS550.png', 599.99, NULL, 1, 'Canon EOS 550 в стильном чёрном цвете.', '["Автоматический фокус","RAW режим","Съёмка с Live View"]', 'Та же камера, но в другом оформлении. Подходит для фото и видео.', '{"Матрица":["18 МП","CMOS сенсор"],"Дисплей":["3 дюйма","Поворотный"],"Память":["SD, SDHC, SDXC"]}', 'canon,eos,камера,фотоаппарат,черный'),
('20469731', 'Canon EOS 550 (с расширенным комплектом)', '/assets/photocamera/canonEOS550.png', 599.99, NULL, 0, 'Камера + сумка + карта памяти', '["Готовый комплект","Удобство в поездках","Быстрый старт"]', 'Этот комплект включает всё необходимое для начала съёмки — идеален для подарка.', '{"Комплектация":["Камера","Сумка","SD-карта 32ГБ"],"Вес":["475 г"],"Цвет":["Чёрный"]}', 'canon,eos,камера,фотоаппарат,комплект,сумка,sd'),
('34891234', 'Lenovo IdeaPad 5', '/assets/laptop/lenovo-ideapad5.png', 799.99, NULL, 1, 'Универсальный ноутбук для учёбы, работы и развлечений.', '["Процессор AMD Ryzen 5","IPS экран 15.6\\" Full HD","SSD накопитель 512 ГБ","До 8 часов автономной работы"]', 'Lenovo IdeaPad 5 — это сбалансированный ноутбук, подходящий для большинства повседневных задач. Благодаря производительному процессору, качественному экрану и быстрому SSD-диску вы сможете комфортно учиться, работать и смотреть фильмы.', '{"Экран":["15.6 дюймов","1920x1080 (Full HD)","IPS матрица"],"Процессор и ОЗУ":["AMD Ryzen 5 5500U","8 ГБ DDR4"],"Хранение данных":["512 ГБ SSD"],"Интерфейсы":["HDMI","USB-C","Wi-Fi 5","Bluetooth 5.0"],"Операционная система":["Windows 11 Home"]}', 'lenovo,ideapad,ноутбук,laptop,учеба,работа'),
('42739561', 'Apple MacBook Air M2', '/assets/laptop/macbook-air-m2.png', 1199.99, NULL, 1, 'Лёгкий, мощный и стильный ноутбук от Apple на чипе M2.', '["Чип Apple M2","Retina экран 13.6\\"","Тихая работа без вентиляторов","До 18 часов автономной работы"]', 'MacBook Air с процессором Apple M2 сочетает в себе невероятную производительность, энергоэффективность и стильный дизайн. Подходит как для работы, так и для творчества.', '{"Экран":["13.6 дюйма","Retina","True Tone"],"Процессор и ОЗУ":["Apple M2","8 ГБ RAM"],"Хранение данных":["256 ГБ SSD"],"Интерфейсы":["2 x Thunderbolt / USB 4","MagSafe 3","Wi-Fi 6","Bluetooth 5.0"],"Операционная система":["macOS Ventura"]}', 'apple,macbook,air,ноутбук,laptop,m2'),
('58391027', 'ASUS ROG Zephyrus G14', '/assets/laptop/asus-rog-g14.png', 1599.99, NULL, 1, 'Игровой ноутбук с компактным дизайном и максимальной мощностью.', '["NVIDIA GeForce RTX 4060","AMD Ryzen 9 7940HS","165 Гц QHD экран","Тонкий и лёгкий корпус"]', 'ASUS ROG G14 — это один из самых мощных компактных игровых ноутбуков. Он сочетает в себе высокую производительность и премиальные технологии охлаждения.', '{"Экран":["14 дюймов","QHD (2560x1440)","165 Гц","IPS"],"Процессор и ОЗУ":["Ryzen 9 7940HS","16 ГБ DDR5"],"Хранение данных":["1 ТБ SSD"],"Графика":["NVIDIA GeForce RTX 4060 8GB"],"Операционная система":["Windows 11 Pro"]}', 'asus,rog,zephyrus,ноутбук,laptop,gaming,игровой');
